import sys

def main():
    line = sys.stdin.readline().strip()
    if '=' in line:
        n = int(line.split('=')[1])
    else:
        n = int(line)

    if n == 0:
        print(-1)
        return

    digits = [0] * n

    while True:
        result = []
        for d in digits:
            if d == -1:
                result.append('T')
            else:
                result.append(str(d))
        print(''.join(result))

        carry = 1
        for i in range(n):
            digits[i] += carry
            if digits[i] == 2:
                digits[i] = -1
                carry = 1
            else:
                carry = 0
                break

        if carry == 1:
            break

if __name__ == "__main__":
    main()
